styl:
.iq-combo-socials-row--socials{display:inline-block;font-size:0;margin:0 auto}
@media screen and (max-width:600px){.iq-combo-socials-row--socials{width:100%!important}}
.iq-combo-socials-row--socials a{display:inline-block;vertical-align:middle;margin:0 10px}
@media screen and (max-width:600px){.iq-combo-socials-row--socials a{margin-bottom:10px!important}}
.iq-combo-socials-row--soc-icon{float:none!important;max-width:24px}
.iq-combo-socials-row--fb{max-width:24px;margin-right:6px}
.iq-combo-socials-row--twitter{max-width:24px;margin:0 6px}
.iq-combo-socials-row--you{max-width:24px;margin:0 6px}
.iq-combo-socials-row--ig{max-width:24px;margin-left:6px}
